  Status s = dockerApi("/images/json", tree);
  if (!s.ok()) {
    VLOG(1) << "Error getting docker images: " << s.what();
    return;
  }
  for (const auto& entry : tree) {
    try {
      const pt::ptree& node = entry.second;
      std::string id = node.get<std::string>("Id", "");
      if (boost::starts_with(id, "sha256:")) {
