 * JSON from containerd or CRI-O. Layer order is normalized to start at 1 for
 * the base layer.
 */
Status parseContainerImageLayers(const std::string& runtime,
                                 const std::string& image_id,
                                 const std::string& inspect_json,
                                 QueryData& rows);

